#pragma once

// docs/CLI.md, generated from the two flag tables (runtime/cli_flags.hpp,
// tools/cuervo_tools/cli_flags.hpp) by `cuervo-tools cli-docs`. The ctest
// `cli_reference_up_to_date` runs it with --check, so the file can't drift.

#include <string>

#include "runtime/cli_flags.hpp"
#include "tools/cuervo_tools/cli_flags.hpp"

namespace cuervo::tools {

inline std::string generate_cli_docs() {
    std::string out =
        "# Command-line reference\n\n"
        "<!-- Generated by `cuervo-tools cli-docs -o docs/CLI.md` from runtime/cli_flags.hpp and\n"
        "     tools/cuervo_tools/cli_flags.hpp. Do not edit by hand; the ctest `cli_reference_up_to_date`\n"
        "     fails when this file is stale. -->\n\n"
        "The same tables print `cuervo --help` and `cuervo-tools --help`.\n\n"
        "## cuervo\n\n"
        "```\n"
        "cuervo --game <dir> | --pack <game.pak> [options]\n"
        "cuervo --demo vector|particles [options]\n"
        "cuervo --svg <file> [options]\n"
        "cuervo --svg <file.svg> --export <file.evec>\n"
        "cuervo --font <file.ttf> --export <file.efont>\n"
        "cuervo --dap\n"
        "```\n\n";
    out += cli::markdown(cli::runtime_table(), "###");
    out += "### Screenshot tick\n\n"
           "`--screenshot` simulates exactly one tick per frame up to the capture tick, draws that state and exits, "
           "so both backends produce comparable images. The capture tick defaults to **" +
           std::to_string(cli::default_screenshot_tick) +
           "**; `--screenshot-tick <n>` or `CUERVO_SCREENSHOT_TICK=<n>` change it (0 is the very first rendered frame, "
           "and the flag wins over the variable).\n\n"
           "### Scripted input (`--press`)\n\n"
           "`--press` (or `CUERVO_PRESS`) is a comma-separated list. Each entry names a tick or an inclusive range "
           "of ticks, a colon, and what to do:\n\n"
           "| Entry | Meaning |\n| --- | --- |\n"
           "| `60:ui_accept` | hold the action `ui_accept` on tick 60 |\n"
           "| `10-20:ui_click` | hold `ui_click` for ticks 10 to 20 |\n"
           "| `60-300:move=1,0` | push the two-dimensional axis `move` to x = 1, y = 0 for ticks 60 to 300 |\n\n"
           "Axis values are in [-1, 1] and replace what the devices would give for those ticks; they are stored in the "
           "same input frames as device input, so a `--record`ed run replays them. An entry naming an unknown "
           "action or axis is ignored with a warning.\n\n"
           "### Exit codes\n\n"
           "| Code | Meaning |\n| --- | --- |\n"
           "| 0 | ok |\n"
           "| 1 | any other failure (a bad flag, no device, an unwritable file); a replay mismatch also exits 1 |\n"
           "| 2 | the scripts did not compile |\n"
           "| 3 | a script panicked |\n\n"
           "## cuervo-tools\n\n"
           "```\n";
    for (const Command& c : command_table()) out += "cuervo-tools " + std::string(c.usage) + "\n";
    out += "```\n\n| Command | Description |\n| --- | --- |\n";
    for (const Command& c : command_table()) out += "| `" + std::string(c.name) + "` | " + std::string(c.help) + " |\n";
    out += "\n";
    out += cli::markdown(tools_table(), "###");
    out += "### Exit codes\n\n" + std::string(tools_exit_codes_text) + ".\n";
    return out;
}

} // namespace cuervo::tools
